// Tests for the menstrual cycle log. Run: npm test. Code generated by Claude (Anthropic), an AI system.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { cycleSummary, lowDaysByPhase } from '../src/cycle.js';

const DAY = 24 * 60 * 60 * 1000;
const T0 = new Date('2026-06-01T07:00:00Z').getTime();
const at = (d) => new Date(T0 + d * DAY).toISOString();
const log = (pairs) => pairs.map(([d, value]) => ({ time: at(d), value }));

test('regular cycles: cycle day, average length, period length and the next expected start', () => {
  const s = cycleSummary(log([[0, 'period_start'], [4, 'period_end'], [28, 'period_start'], [32, 'period_end'], [56, 'period_start'], [61, 'period_end']]), new Date(T0 + 66 * DAY));
  assert.equal(s.average, 28);
  assert.equal(s.cycleDay, 11);
  assert.equal(s.periodDays, 5);
  assert.equal(s.nextExpected.toISOString(), at(84));
  assert.deepEqual(s.flags, []);
});

test('two cycles in a row longer than 45 days are flagged, as the Endocrine Society advises a check-up', () => {
  const s = cycleSummary(log([[0, 'period_start'], [50, 'period_start'], [100, 'period_start']]), new Date(T0 + 101 * DAY));
  assert.ok(s.flags.includes('long-cycles'));
});

test('no period for more than 3 months is flagged', () => {
  const s = cycleSummary(log([[0, 'period_start']]), new Date(T0 + 95 * DAY));
  assert.ok(s.flags.includes('no-period'));
});

test('with suppression on there are no predictions and no flags: the choice is the person\'s', () => {
  const s = cycleSummary(log([[0, 'period_start'], [1, 'suppression_on']]), new Date(T0 + 120 * DAY));
  assert.equal(s.suppressed, true);
  assert.equal(s.nextExpected, null);
  assert.deepEqual(s.flags, []);
});

test('low days are counted by cycle phase, only from the person\'s own data', () => {
  const starts = [T0, T0 + 28 * DAY];
  const days = [[at(2), true], [at(3), false], [at(10), true], [at(30), true]];
  const phases = lowDaysByPhase(starts, days);
  assert.deepEqual(phases.map((p) => [p.low, p.days]), [[2, 3], [1, 1], [0, 0], [0, 0]]);
});
